#include <iostream>

int main() {
    // Phase 1: Initialization
    int total{0};
    unsigned int counter{1};
    constexpr unsigned int totalStudents{10};

    // Phase 2: Processing with counter-controlled iteration
    while (counter <= totalStudents) {
        int grade{0};
        if (std::cin >> grade) {
            total += grade;
            counter += 1;
        } else {
            break;
        }
    }

    // Phase 3: Compute and display average
    if (counter > 1) {
        int average = total / static_cast<int>(totalStudents);
        std::cout << "Total of all 10 grades is " << total << "\n";
        std::cout << "Class average is " << average << "\n";
    }

    return 0;
}
